mapper.select:
    (select mer.crt_name consumerName,pbi.name as patientName,1 type ,DATE_FORMAT(mer.crt_time,'%Y-%m-%d %H:%i:%s') operatingTime,
    (mer.expend_principal+mer.expend_gift) rechargePrincipal from member_expend_record mer
    left JOIN patient_base_info pbi on mer.patient_id = pbi.id
    where mer.inservice = 1  and DATE_FORMAT(mer.crt_time,'%Y-%m') >
    DATE_FORMAT(date_sub(curdate(), interval 12 month),'%Y-%m')
    and mer.member_id = #{memberId}

            and mer.patient_id = #{patientId}

    )
    UNION
    (select crt_name consumerName,'--' patientName, 0 type,DATE_FORMAT(crt_time,'%Y-%m-%d %H:%i:%s') operatingTime,(recharge_principal+ifnull(recharge_bonus,0)) rechargePrincipal
    from member_recharge_record
    where inservice = 1 and type IN (0, 6, 7) and DATE_FORMAT(crt_time,'%Y-%m') >
    DATE_FORMAT(date_sub(curdate(), interval 12 month),'%Y-%m')
    and member_id = #{memberId}
    )
    UNION
    (select mrr.crt_name consumerName,'--' patientName,2 type,DATE_FORMAT(mrr.crt_time,'%Y-%m-%d %H:%i:%s') operatingTime,mrr.actual_return_amount rechargePrincipal
    from member_return_record  mrr
      left JOIN patient_base_info pbi on mrr.patient_id = pbi.id
      where mrr.inservice = 1 and DATE_FORMAT(mrr.crt_time,'%Y-%m') >
      DATE_FORMAT(date_sub(curdate(), interval 12 month),'%Y-%m')
      and mrr.member_id = #{memberId}

            and mrr.patient_id = #{patientId}

)

    (select mer.crt_name as consumerName,pbi.name as patientName,1 type ,DATE_FORMAT(mer.crt_time,'%Y-%m-%d %H:%i:%s') operatingTime,
    (mer.expend_principal+mer.expend_gift) rechargePrincipal from prepaid_expend_record mer
    left JOIN patient_base_info pbi on mer.patient_id = pbi.id
    where mer.inservice = 1 and DATE_FORMAT(mer.crt_time,'%Y-%m') >
    DATE_FORMAT(date_sub(curdate(), interval 12 month),'%Y-%m')
    and mer.prepaid_id = #{memberId}

        and mer.patient_id = #{patientId}

    )
    UNION
    (select crt_name consumerName,'--' patientName, 0 type,DATE_FORMAT(crt_time,'%Y-%m-%d %H:%i:%s') operatingTime,(recharge_principal+ifnull(recharge_bonus,0)) rechargePrincipal
    from prepaid_recharge_record
    where inservice = 1 and type = 0 and DATE_FORMAT(crt_time,'%Y-%m') >
    DATE_FORMAT(date_sub(curdate(), interval 12 month),'%Y-%m')
    and prepaid_id = #{memberId}
    )
    UNION
    (select mrr.crt_name consumerName,'--' patientName,2 type,DATE_FORMAT(mrr.crt_time,'%Y-%m-%d %H:%i:%s') operatingTime,mrr.actual_return_amount rechargePrincipal
    from prepaid_return_record  mrr
      left JOIN patient_base_info pbi on mrr.patient_id = pbi.id
      where mrr.inservice = 1 and DATE_FORMAT(mrr.crt_time,'%Y-%m') >
      DATE_FORMAT(date_sub(curdate(), interval 12 month),'%Y-%m')
      and mrr.prepaid_id = #{memberId}

        and mrr.patient_id = #{patientId}

)

select id,patient_id masterCardId, member_type_id masterCardTypeId,
(select name from patient_base_info where id = patient_id) masterName,card_number masterCardNumber,point,crt_time crtTime
from patient_member_info where patient_id = #{form.patientId}

select sum(amount) from (
    select IFNULL(sum(t.credit_amount),0) amount from member_recharge_toll_record t

        t.inservice = 1

            and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


            and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


            and t.org_id = #{query.orgId}


            and t.payment_id = #{query.payId}


    union all
    select IFNULL(sum(t.credit_amount),0) amount from prepaid_recharge_toll_record t

        t.inservice = 1

            and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


            and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


            and t.org_id = #{query.orgId}


            and t.payment_id = #{query.payId}


) as total

select sum(amount) from (
select IFNULL(sum(t.actual_return_amount),0) amount from member_return_record t

    t.inservice = 1

        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


        and t.org_id = #{query.orgId}


        and t.return_way_id = #{query.payId}


union all
select IFNULL(sum(t.actual_return_amount),0) amount from prepaid_return_record t

    t.inservice = 1

        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')


        and DATE_FORMAT(t.crt_time,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')


        and t.org_id = #{query.orgId}


        and t.return_way_id = #{query.payId}


) as total
